-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "esES" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.mage.fire.Name"] = "Fuego"
L["rm.era.mage.fire.Description"] = "Fuego del nivel 10 al 60, elegida cuando tienes puntos en Fuego y ninguno en Escarcha, o Fuego es tu árbol principal. Piroexplosión (si no, Bola de Fuego) abre el combate; Piroexplosión tras Presencia mental; Chamuscar mantiene cinco acumulaciones de Vulnerabilidad de Fuego con Chamuscar mejorado sobre objetivos que vayan a sobrevivir; Explosión de Fuego y Chamuscar rematan; Bola de Fuego hace de relleno. Con tres o más enemigos trabados en combate: Ola explosiva, Fogonazo, Deflagración Arcana, Cono de frío y Ventisca. Recordatorios: Combustión con cinco acumulaciones de Chamuscar contra élites y en combates largos, armadura, Intelecto Arcano, gemas de maná, Barrera de hielo, Escudo de maná, Evocación, Contrahechizo, Deshacer maldición inferior, Bloqueo de hielo y Presencia mental. Desactivado por defecto: intercalar Explosión de Fuego siempre que esté lista."
L["rm.era.mage.fire.warcrafttavern.Name"] = "Fuego (Warcraft Tavern)"
L["rm.era.mage.fire.warcrafttavern.Description"] = "Fuego según Warcraft Tavern, una alternativa a la rotación integrada de Fuego recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. Combustión se gasta al iniciar el combate contra élites y jefes en lugar de esperar a las acumulaciones de Chamuscar; Piroexplosión abre el combate; Chamuscar mantiene cinco acumulaciones con Chamuscar mejorado; Bola de Fuego hace de relleno; Explosión de Fuego solo en movimiento. Contra grupos de enemigos: primero Fogonazo, después Deflagración Arcana, Cono de frío y Ola explosiva de cerca, y Ventisca a distancia. Los mismos recordatorios que la rotación integrada de Fuego."
L["rm.era.mage.frost.Name"] = "Escarcha"
L["rm.era.mage.frost.Description"] = "Escarcha del nivel 1 al 60, también para builds de Arcano y la opción predeterminada del mago antes de los talentos. Descarga de Escarcha (Bola de Fuego antes del nivel 4); Nova de Escarcha cuando un enemigo te alcanza, salvo contra jefes de banda; Misiles Arcanos cuando un enemigo te alcanza si tienes Misiles Arcanos mejorados; Cono de frío, Deflagración Arcana y Ventisca cuando hay tres o más enemigos trabados en combate; Explosión de Fuego en movimiento con maná de sobra; Explosión de Fuego y la varita rematan a los enemigos normales en solitario; varita cuando te quedas sin maná. Recordatorios: armadura (Armadura de hielo en solitario, Armadura de mago en grupo, sin sustituir nunca la que hayas elegido), Intelecto Arcano, conjurar y usar gemas de maná, Barrera de hielo, Escudo de maná, Evocación, Contrahechizo, Deshacer maldición inferior, Bloqueo de hielo, Mordedura helada, Poder Arcano y Presencia mental. Desactivados por defecto: el Fogonazo con Trizar y la Descarga de Escarcha de rango 1 para acumular Escalofrío del invierno. Traslación, Polimorfia, el kiteo y la elección de objetivo quedan a tu cargo."
L["rm.era.mage.frost.icyveins.Name"] = "Escarcha, farmeo de área (Icy Veins)"
L["rm.era.mage.frost.icyveins.Description"] = "Subida de nivel con Ventisca según la guía de farmeo de área de Icy Veins, elegida automáticamente cuando juegas en solitario con Ventisca mejorada. Desde dos enemigos trabados en combate: Nova de Escarcha sobre el grupo, Cono de frío mientras Nova se recarga, Ventisca cuando no hay nada a tu lado y Deflagración Arcana cuando sí lo hay; Descarga de Escarcha contra un solo objetivo, y Explosión de Fuego y la varita para rematar. Escudo de maná y Barrera de hielo se ponen antes de cada combate. Reunir al grupo de enemigos, Traslación y el kiteo quedan a tu cargo."
L["rm.forever.mage.arcane.Name"] = "Arcano"
L["rm.forever.mage.arcane.Description"] = "Arcano una vez que Arcano es tu árbol de talentos principal con 11 puntos y conoces Explosión Arcana. Inicia el combate con Descarga de Escarcha en solitario o Explosión Arcana en grupo; después Misiles Arcanos con Tromba de misiles, Explosión Arcana con Conjuro libre, Cólera Arcana con tres acumulaciones de Explosión Arcana, Explosión Arcana hasta cuatro acumulaciones contra élites y dos contra otros objetivos mientras puedas permitírtelo (el maná está oculto en Forever), después Descarga de Pirofrío, Descarga de Escarcha o Bola de Fuego para buscar Tromba de misiles, y una varita en solitario cuando no puedes permitirte un hechizo. Sin Cólera Arcana (el diseño anterior de la beta), Explosión de Fuego gasta las acumulaciones. En movimiento: Explosión de Fuego. Con tres o más enemigos luchando contra ti: Deflagración Arcana. Recordatorios: Presencia mental y Poder Arcano contra élites (Poder Arcano ya no espera a que tengas la mitad del maná), además de los recordatorios de mantenimiento del mago."
L["rm.forever.mage.fire.Name"] = "Fuego"
L["rm.forever.mage.fire.Description"] = "Fuego una vez que Fuego es tu árbol de talentos principal con 11 puntos (la fila de Piroexplosión). Inicia el combate con Piroexplosión contra élites y, si no, con Descarga de Pirofrío o Bola de Fuego; después Piroexplosión con tres acumulaciones de Calentamiento, Lanza de hielo con Dedos de Escarcha o sobre un objetivo congelado (híbridos de Fuego/Escarcha), Explosión de Fuego cada vez que esté disponible, Chamuscar para mantener tus cinco acumulaciones de Vulnerabilidad de Fuego contra élites, Descarga de Pirofrío (desde el 40) o Bola de Fuego, y varita en solitario cuando no puedes permitirte un hechizo. En movimiento: Explosión de Fuego o Lanza de hielo. Con cuatro o más enemigos luchando contra ti: Fogonazo, Ola explosiva y Deflagración Arcana. Chamuscar empieza las acumulaciones solo cuando tienes Chamuscar mejorado; un Chamuscar a corta distancia está desactivado hasta que lo actives. Recordatorios: Combustión y Presencia mental contra élites, además de los recordatorios de mantenimiento del mago."
L["rm.forever.mage.fire.icyveins.Name"] = "Fuego para subir de nivel (Icy Veins)"
L["rm.forever.mage.fire.icyveins.Description"] = "La build de Fuego para subir de nivel de Icy Veins sin Chamuscar mejorado, una alternativa a la rotación integrada de Fuego recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. Inicia el combate con Piroexplosión, usa Explosión de Fuego para gastar Estela de Fuego, Chamuscar mientras el enemigo se acerca (la salud del objetivo está oculta en Forever, así que los remates sobre objetivos con poca salud los decides tú), y después Descarga de Pirofrío (desde el 40) o Bola de Fuego. La misma área, movimiento, varita y recordatorios que la rotación integrada de Fuego, sin Combustión ni Presencia mental."
L["rm.forever.mage.frost.Name"] = "Escarcha"
L["rm.forever.mage.frost.Description"] = "Escarcha del nivel 1 al 60, y la opción predeterminada del mago de Forever antes de los hechizos de talento (Bola de Fuego hasta Descarga de Escarcha a nivel 4). Inicia el combate con Descarga de Escarcha; después Lanza de hielo con Dedos de Escarcha o sobre un objetivo congelado (también mientras aún se lanza Descarga de Escarcha, para cancelarla o agruparlas), Cono de frío con cinco acumulaciones de Escalofrío del invierno, Misiles Arcanos con Tromba de misiles, Descarga de Escarcha y una varita en solitario cuando no puedes permitirte Descarga de Escarcha. En movimiento: Lanza de hielo; si no, Explosión de Fuego. Con tres o más enemigos luchando contra ti: Cono de frío; con cinco o más: Ventisca, o Deflagración Arcana si un enemigo te está atacando. Se incluye el área de Fogonazo y Deflagración Arcana de Warcraft Tavern, pero desactivada. Recordatorios: Intelecto Arcano, armadura (de hielo o de escarcha en solitario, Armadura de mago en grupo, sin sustituir nunca la que hayas elegido), Barrera de hielo, Contrahechizo, Deshacer maldición inferior, Nova de Escarcha cuando un enemigo te alcanza y Mordedura helada. La salud y el maná están ocultos para los addons en Forever, así que rematar objetivos con poca salud con Explosión de Fuego, Evocación y Bloqueo de hielo lo decides tú; Traslación, el kiteo, Polimorfia y las gemas de maná quedan también a tu cargo."
L["rm.mop.mage.arcane.Name"] = "Recomendada"
L["rm.mop.mage.arcane.Description"] = "Recomendada para Arcano, del nivel 10 al 90 (seleccionada en la especialización Arcano). Explosión Arcana acumula cuatro Cargas Arcanas; con cuatro, una activación de ¡Misiles Arcanos! se gasta con Misiles y, sin ella, sale Tromba Arcana en cuanto tu maná baja del 90 %. Por encima del 95 % de maná sigue lanzando Explosión, que es como lo juega el simulador. Nunca deja Misiles acumulado en dos activaciones, Tromba se lanza antes de que Alterar el tiempo te devuelva atrás, y con dos o más enemigos Tromba sale cada cuatro cargas; Cono de frío y Deflagración Arcana cuando hay cinco cerca. Mantiene tu bomba de talento, y Explosión de Fuego o Lanza de hielo en movimiento sin Témpanos de hielo. Recordatorios: Poder Arcano y Alterar el tiempo con cuatro cargas y una activación, Armadura de Escarcha (Armadura de arrabio antes del 54), Luminosidad Arcana, Contrahechizo, Gema de maná, Reflejo exacto, Barrera de hielo, Témpanos de hielo, y Runa de poder o Invocación. Distorsión temporal, Robar hechizo y Presencia mental están desactivados; Runa de poder sigue teniendo que colocarse a mano."
L["rm.mop.mage.arcane.icyveins.Name"] = "Tromba con cuatro cargas (Icy Veins)"
L["rm.mop.mage.arcane.icyveins.Description"] = "La regla de Arcano de las guías (Icy Veins, Wowhead, Method, wowtbc.gg), una alternativa a la rotación integrada de Arcano recomendada: con cuatro Cargas Arcanas, Misiles Arcanos si hay una activación y, si no, Tromba Arcana, tengas el maná que tengas; Misiles solo con cuatro cargas. Todo lo demás (Alterar el tiempo, bombas, área, movimiento, recordatorios) coincide con la recomendada, salvo que Poder Arcano se sugiere con cuatro cargas sin esperar a una activación. Desactivada por defecto: actívala y desactiva la rotación integrada de Arcano recomendada, o súbele la prioridad."
L["rm.mop.mage.fire.Name"] = "Recomendada"
L["rm.mop.mage.fire.Description"] = "Recomendada para Fuego, del nivel 10 al 90 (seleccionada en la especialización Fuego). Abre con una Piroexplosión lanzada entera, y después Explosión infernal (Explosión de Fuego antes del 24) convierte Calentamiento en una activación de ¡Piroexplosión!, que se lanza al momento salvo que Combustión esté a punto de terminar su tiempo de reutilización; después espera al siguiente Calentamiento mientras lanzas Bola de Fuego. Combustión se lanza justo después de una Piroexplosión mientras Ignición y la quemadura de Piroexplosión están en el objetivo; el addon no puede ver lo grande que es Ignición, así que juzga tú si es débil. Mantiene tu bomba de talento, la extiende con Explosión infernal cuando dos o más enemigos luchan contra ti, Cono de frío y Deflagración Arcana contra cinco cercanos, y Agostar en movimiento. Recordatorios: Armadura de arrabio, Presencia mental, Alterar el tiempo con ambas activaciones, Gema de maná, Luminosidad Arcana, Contrahechizo, Reflejo exacto, Barrera de hielo, Témpanos de hielo, e Invocación o Runa de poder. Aliento de dragón, Distorsión temporal y Robar hechizo están desactivados."
L["rm.mop.mage.fire.icyveins.Name"] = "Retener ¡Piroexplosión! (Icy Veins)"
L["rm.mop.mage.fire.icyveins.Description"] = "El Fuego de Icy Veins, Method y wowtbc.gg, una alternativa a la rotación integrada de Fuego recomendada: una activación de ¡Piroexplosión! se retiene hasta que se le une un Calentamiento, y entonces se lanza junto con tu Bola de Fuego; solo se gasta sola cuando está a punto de expirar. Todo lo demás coincide con la recomendada. Desactivada por defecto: actívala y desactiva la rotación integrada de Fuego recomendada, o súbele la prioridad."
L["rm.mop.mage.frost.Name"] = "Recomendada"
L["rm.mop.mage.frost.Description"] = "Escarcha del nivel 10 al 90 (seleccionada en la especialización Escarcha). Lanza de hielo con dos Dedos de Escarcha, Descarga de Pirofrío con Congelación cerebral, tu bomba de talento, Orbe congelado, Lanza de hielo con un Dedos de Escarcha y Descarga de Escarcha; desde el 87, una activación se retiene para Alterar el tiempo cuando le faltan menos de 10 segundos. Con dos o más enemigos: Orbe congelado, Cono de frío y Deflagración Arcana cuando están cerca, y Ventisca cuando cuatro se quedan quietos. Lanza de hielo y Explosión de Fuego en movimiento sin Témpanos de hielo. Recordatorios: Elemental de agua, Congelar sobre cualquier cosa que no sea un jefe (colócalo tú), Venas heladas sincronizado con Alterar el tiempo, Alterar el tiempo con dos Dedos de Escarcha durante Venas heladas, Armadura de Escarcha (Armadura de arrabio antes del 54), Gema de maná, Luminosidad Arcana, Contrahechizo, Reflejo exacto, Barrera de hielo, Témpanos de hielo, e Invocación o Runa de poder. Mordedura de frío, Presencia mental, Distorsión temporal y Robar hechizo están desactivados."
L["rm.mop.mage.unspecialized.Name"] = "Antes de una especialización"
L["rm.mop.mage.unspecialized.Description"] = "Para los niveles 1 a 9, y cualquier mago que aún no haya elegido especialización. Descarga de Pirofrío, Explosión de Fuego para rematar un objetivo o en movimiento, Lanza de hielo en movimiento una vez aprendida, y Deflagración Arcana cuando hay tres o más enemigos al alcance cuerpo a cuerpo. Recordatorios: Nova de Escarcha cuando un enemigo te alcanza, Contrahechizo, y Armadura de arrabio y Luminosidad Arcana si llegas a ellas. Elegir una especialización en el nivel 10 cambia a la rotación integrada de esa especialización."
L["rm.retail.mage.arcane.Name"] = "Ayudante de combate de Blizzard"
L["rm.retail.mage.arcane.Description"] = "Recomendada para Arcano. Resalta el próximo hechizo que sugiere el Ayudante de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight; espera mientras lanzas o canalizas. Junto a él, recordatorios de lo que el Ayudante de combate deja a tu cargo: Oleada Arcana en combate, Intelecto Arcano fuera de combate, Contrahechizo ante un lanzamiento interrumpible, Barrera prismática siempre que esté lista en combate y tu habilidad racial en combate. Los lanzamientos enemigos están ocultos en combate, así que Contrahechizo solo se ilumina donde el juego los muestra; la salud está oculta en Retail, así que Bloque de hielo y otros botones de emergencia los decides tú. Reflejo exacto, Alterar el tiempo, Traslación y los abalorios quedan a tu cargo."
L["rm.retail.mage.arcane.guide.Name"] = "Referencia (Icy Veins y SimulationCraft)"
L["rm.retail.mage.arcane.guide.Description"] = "Solo de referencia, desactivada por defecto: la prioridad de Arcano de las guías. Andanada Arcana y Lanzamiento libre están ocultos para los addons en el combate de Midnight (solo las cargas Arcanas siguen visibles), así que no puede funcionar allí; el maná está oculto en Retail, así que la Evocación con poco maná la decides tú; léela o duplícala para experimentar. Inicia el combate con Explosión Arcana. Furiasolar: Misiles Arcanos con Lanzamiento libre por debajo de 12 de Andanada, Descarga prismática fuera de Alma Arcana, Tromba Arcana con cuatro cargas y 12 de Andanada con Lanzamiento libre o 25 de Andanada, o con Alma Arcana con cualquier número de cargas, Descarga prismática, Orbe Arcano con menos de tres cargas, Pulso Arcano contra tres enemigos o sin cargas, Explosión Arcana. Lanzahechizos (con Hechicería astillada aprendida): Descarga prismática, Orbe contra grupos de enemigos, Tromba con 20 de Andanada (contra dos o más enemigos, solo con cuatro cargas), Misiles con Lanzamiento libre por debajo de 15 de Andanada, Orbe y Pulso con menos de tres cargas (sin Pulso durante Oleada Arcana), Explosión Arcana. Tromba Arcana cuando no se puede lanzar Explosión. Recordatorios: Oleada Arcana, Toque de los magi tras una Tromba o una Descarga prismática durante Oleada o mucho antes de ella, Presencia mental sin cargas tras una Tromba, además de los recordatorios de la rotación integrada del Ayudante de combate."
L["rm.retail.mage.fire.Name"] = "Ayudante de combate de Blizzard"
L["rm.retail.mage.fire.Description"] = "Recomendada para Fuego. Resalta el próximo hechizo que sugiere el Ayudante de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight; espera mientras lanzas o canalizas. Junto a él, recordatorios de lo que el Ayudante de combate deja a tu cargo: Combustión en combate, Intelecto Arcano fuera de combate, Contrahechizo ante un lanzamiento interrumpible, Barrera llameante siempre que esté lista en combate y tu habilidad racial en combate. Los lanzamientos enemigos están ocultos en combate, así que Contrahechizo solo se ilumina donde el juego los muestra; la salud está oculta en Retail, así que Bloque de hielo y otros botones de emergencia los decides tú."
L["rm.retail.mage.fire.guide.Name"] = "Referencia (Icy Veins, Wowhead y SimulationCraft)"
L["rm.retail.mage.fire.guide.Description"] = "Solo de referencia, desactivada por defecto: la prioridad de Fuego de las guías. Buena racha, Calentamiento, Piroestallido y las cargas de Explosión de Fuego están ocultos en el combate de Midnight, así que no puede funcionar allí. Explosión de Fuego mientras termina un lanzamiento para convertir Calentamiento en Buena racha; inicia el combate con Piroexplosión. Piroexplosión (Fogonazo contra cuatro o más enemigos) con Hipertermia, Meteoro, Piroexplosión con Buena racha, Explosión de Fuego con Calentamiento dentro de Combustión, Piroexplosión con Piroestallido, Agostar con Fulgor de calor o en movimiento, Explosión de Fuego con Calentamiento y, después, Descarga de Pirofrío o Bola de Fuego. Recordatorios: Combustión al terminar un lanzamiento con tiempo de lanzamiento, Barrera llameante y los recordatorios de utilidad. Esperar a Acelerador de ignición y hacer coincidir Meteoro con Combustión quedan a tu cargo."
L["rm.retail.mage.frost.Name"] = "Ayudante de combate de Blizzard"
L["rm.retail.mage.frost.Description"] = "Recomendada para Escarcha. Resalta el próximo hechizo que sugiere el Ayudante de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight; espera mientras lanzas o canalizas. Junto a él, recordatorios de lo que el Ayudante de combate deja a tu cargo: Invocar elemental de agua cuando tienes el talento y ningún elemental, Intelecto Arcano fuera de combate, Contrahechizo ante un lanzamiento interrumpible, Barrera de hielo siempre que esté lista en combate y tu habilidad racial en combate. Los lanzamientos enemigos están ocultos en combate, así que Contrahechizo solo se ilumina donde el juego los muestra; la salud está oculta en Retail, así que Bloque de hielo y otros botones de emergencia los decides tú."
L["rm.retail.mage.frost.guide.Name"] = "Referencia (Icy Veins y SimulationCraft)"
L["rm.retail.mage.frost.guide.Description"] = "Solo de referencia, desactivada por defecto: la prioridad de Escarcha de las guías para cada árbol de héroe. Las activaciones, las acumulaciones de Congelación y los tiempos de reutilización están ocultos en el combate de Midnight, así que no puede funcionar allí. Inicia el combate con Descarga de Pirofrío o Descarga de Escarcha. Pirofrío (con Descarga de Pirofrío aprendida): Pica glacial cuando está lista, Lluvia de cometas contra uno o dos enemigos, Aluvión con Congelación cerebral sin Vacío térmico, Lanza de hielo con dos acumulaciones de Dedos de Escarcha, Rayo de Escarcha, Orbe congelado, Ventisca con Lluvia congelante contra tres enemigos, Lanza de hielo con Dedos de Escarcha si tienes Vacío térmico o con doce de Congelación, Aluvión, Nova de hielo o Cono de frío contra cinco y, después, Pica glacial o Descarga de Pirofrío. Lanzahechizos: Lluvia de cometas, Aluvión con Congelación cerebral, Lanza de hielo con dos Dedos, Orbe congelado, Pica glacial cuando está lista, Ventisca con Lluvia congelante, Lanza de hielo con Dedos de Escarcha o con seis de Congelación, Rayo de Escarcha, Aluvión, Nova de hielo o Cono de frío contra cuatro, Ventisca contra siete y, después, Pica glacial o Descarga de Escarcha. Lanza de hielo en movimiento. Recordatorios: Invocar elemental de agua, Barrera de hielo y los recordatorios de utilidad."
L["rm.retail.mage.initial.Name"] = "Ayudante de combate de Blizzard"
L["rm.retail.mage.initial.Description"] = "Recomendada antes de elegir una especialización (mientras el juego informa de la especialización inicial del mago). Resalta el próximo hechizo que sugiere el Ayudante de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight; espera mientras lanzas o canalizas. Junto a él, los recordatorios que comparten todas las rotaciones integradas de mago, cada uno cuando conoces su hechizo. Cuando elijas una especialización a nivel 10, las rotaciones integradas de esa especialización toman el relevo."
L["rm.sod.mage.arcane.Name"] = "Arcano (SoD)"
L["rm.sod.mage.arcane.Description"] = "Daño Arcano de la Temporada del Descubrimiento, elegida cuando Arcano es tu árbol principal y tienes grabada la runa de Explosión Arcana. Misiles Arcanos con Tromba de misiles; Tromba Arcana con cuatro acumulaciones de Explosión Arcana; Descarga de Fuegotorvo cuando es seguro, nunca con cuatro o más acumulaciones de Fuegotorvo; Llama viva cada vez que esté disponible; Explosión Arcana hace de relleno. Tromba Arcana y Explosión de Fuego en movimiento; Llama viva y Deflagración Arcana contra grupos de enemigos. Recordatorios: Poder Arcano contra élites y en combates largos, Presencia mental con Poder Arcano o en movimiento, Venas heladas, Mordedura helada y los demás recordatorios de mago."
L["rm.sod.mage.fire.Name"] = "Fuego (SoD)"
L["rm.sod.mage.fire.Description"] = "Fuego de la Temporada del Descubrimiento del nivel 1 al 60, y la opción predeterminada del mago allí. Usa las runas que tengas grabadas: Piroexplosión con Buena racha al instante; Bomba viva mantenida sobre objetivos que vayan a sobrevivir; Chamuscar con Chamuscar mejorado mientras Vulnerabilidad de Fuego tenga menos de dos acumulaciones o esté a punto de desaparecer; Llama viva cada vez que esté disponible; Descarga de Fuegotorvo con cinco acumulaciones de Vulnerabilidad de Fuego, nunca con cuatro o más acumulaciones de Fuegotorvo (la quinta te mata); Descarga de Pirofrío y, si no, Bola de Fuego. Bomba viva, Llama viva y Explosión de Fuego en movimiento; Llama viva, Bomba viva, Ola explosiva, Cono de frío, Fogonazo y Ventisca contra grupos de enemigos. Recordatorios: Explosión de Fuego con Recalentamiento, Combustión, Venas heladas y Mordedura helada, Armadura de arrabio u otra armadura, Intelecto Arcano, gemas de maná, Barrera de hielo, Escudo de maná, Evocación, Contrahechizo, quitar maldiciones y Bloqueo de hielo. Extender Bomba viva a varios objetivos queda a tu cargo."
L["rm.sod.mage.frost.Name"] = "Escarcha (SoD)"
L["rm.sod.mage.frost.Description"] = "Escarcha de la Temporada del Descubrimiento desde el nivel 10, elegida cuando Escarcha es tu árbol principal. Dedos de Escarcha va a Lanza de hielo con tres o más de tus acumulaciones de Helar y, si no, a Congelación profunda; Descarga de Fuegotorvo cuando se activa Congelación cerebral y, si no, cuando es seguro, nunca con cuatro o más acumulaciones de Fuegotorvo; Bomba viva y Llama viva cuando están grabadas; Descarga de Fríoarcano, si no Descarga de Pirofrío y, si no, Descarga de Escarcha. Lanza de hielo, Orbe congelado, Bomba viva y Explosión de Fuego en movimiento; Orbe congelado, Llama viva, Bomba viva, Ventisca y Cono de frío contra grupos de enemigos. Recordatorios: Orbe congelado, Venas heladas, Mordedura helada, armadura, gemas de maná y los demás recordatorios de mago. Encadenar un hechizo cuando impacta una descarga queda a tu cargo."
L["rm.sod.mage.frost.warcrafttavern.Name"] = "Escarcha, runas de Fuego (SoD, Warcraft Tavern)"
L["rm.sod.mage.frost.warcrafttavern.Description"] = "La build de Escarcha con runas de Fuego de la fase 4 de Warcraft Tavern, una alternativa a la rotación integrada de Escarcha de la Temporada del Descubrimiento recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. Piroexplosión abre el combate; Piroexplosión con Buena racha; Bomba viva siempre activa; Chamuscar hasta cinco acumulaciones con Chamuscar mejorado; Descarga de Fuegotorvo solo cuando se activa Congelación cerebral y nunca con cuatro o más acumulaciones de Fuegotorvo; Descarga de Pirofrío hace de relleno. Bomba viva y Explosión de Fuego en movimiento; Bomba viva, Cono de frío y Ventisca contra grupos de enemigos. Recordatorios: Explosión de Fuego con Recalentamiento, Orbe congelado durante Venas heladas, Venas heladas, Mordedura helada y los demás recordatorios de mago."
L["rm.sod.mage.healer.Name"] = "Sanador (SoD)"
L["rm.sod.mage.healer.Description"] = "Sanación de mago de la Temporada del Descubrimiento, elegida cuando tienes grabada la runa de Regeneración o de Regeneración en masa. Con un objetivo amistoso: Retroceder en el tiempo y Preservación cronostática por debajo de la mitad de la salud, Regeneración cuando falta tu Baliza temporal, Regeneración en masa y Anomalía temporal. Con un objetivo enemigo, daño que sana a tus balizas: Descarga de Fríoarcano para sanadores de Escarcha; si no, Misiles Arcanos con Tromba de misiles, Tromba Arcana con dos acumulaciones de Explosión Arcana, Descarga de Fuegotorvo cuando es seguro (nunca con cuatro o más acumulaciones de Fuegotorvo) y Explosión Arcana. Recordatorios: Poder Arcano, Presencia mental, Orbe congelado y los demás recordatorios de mago. Desactivados por defecto: Deflagración Arcana contra grupos de enemigos, y Lanza de hielo y Congelación profunda para sanadores de Escarcha. Mientras canalizas Regeneración en masa ya se muestra el siguiente hechizo, así que puedes cancelarla de inmediato (su sanación directa es pequeña). Elegir a quién sanar queda a tu cargo."
L["rm.tbc.mage.arcane.Name"] = "Arcano"
L["rm.tbc.mage.arcane.Description"] = "Arcano, elegida cuando Arcano es tu árbol de talentos principal. Antes del nivel 64: Misiles Arcanos, con Descarga de Escarcha cuando escasea el maná. Desde el 64: Explosión Arcana mientras quemas maná (Poder Arcano, Ansia de sangre o más del 35 % de maná); si no, tres acumulaciones de Explosión Arcana y Descarga de Escarcha hasta que estén a punto de desaparecer. Deflagración Arcana y Cono de frío contra tres o más enemigos. Los recordatorios incluyen Poder Arcano, Presencia mental, gema de maná y Evocación."
L["rm.tbc.mage.fire.icyveins.Name"] = "Fuego (Icy Veins)"
L["rm.tbc.mage.fire.icyveins.Description"] = "Fuego según Icy Veins, elegida cuando Fuego es tu árbol de talentos principal. Piroexplosión abre el combate una vez aprendida, Agostar mejorado mantiene cinco acumulaciones de Vulnerabilidad de Fuego, Bola de Fuego hace de relleno y Explosión de Fuego es para moverse; Ola explosiva, Aliento de dragón y Fogonazo contra tres o más enemigos. Recordatorios: Armadura de arrabio, de mago o de hielo, Combustión con el objetivo por debajo del 20 % de salud, gema de maná, Evocación y las utilidades de mago compartidas."
L["rm.tbc.mage.fire.wowhead.Name"] = "Fuego (Wowhead)"
L["rm.tbc.mage.fire.wowhead.Description"] = "Fuego según Wowhead y simulador. Como la rotación integrada de Fuego de Icy Veins, pero intercala Explosión de Fuego siempre que está lista mientras estás quieto (más daño, más maná) y abre con Bola de Fuego en lugar de Piroexplosión. Es una alternativa a la rotación integrada de Fuego de Icy Veins recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad."
L["rm.tbc.mage.frost.Name"] = "Escarcha"
L["rm.tbc.mage.frost.Description"] = "Escarcha del nivel 1 al 70, y la opción predeterminada del mago antes de los talentos. Descarga de Escarcha (Bola de Fuego antes del nivel 4), Nova de Escarcha cuando algo te golpea, Cono de frío con Ventisca o Deflagración Arcana cuando hay tres o más enemigos trabados en combate, Lanza de hielo sobre objetivos congelados y en movimiento, y varita cuando te quedas sin maná. Recordatorios: armadura, Intelecto Arcano, gema de maná, Evocación, Contrahechizo, Robar hechizo, Barrera de hielo, Venas heladas, Golpe frío y elemental de agua. Traslación, Bloqueo de hielo, el kiteo y la elección de objetivo quedan a tu cargo."
